WITH with_windows AS (SELECT *, MAX(amount) OVER w_grp AS running_max_amount, AVG(amount) OVER w_grp AS running_avg_amount, COUNT(amount) OVER w_grp AS running_count_amount FROM payments WHERE TO_DATE(paid_at) >= '2023-04-21' WINDOW w_grp AS (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, DATE_TRUNC('YEAR', paid_at) AS year_start, STDDEV_SAMP(amount) AS amount_stddev, APPROX_PERCENTILE(running_avg_amount, ARRAY(0.25, 0.5, 0.75)) AS running_avg_amount_quartiles, GROUPING_ID() AS gid FROM with_windows GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', paid_at), DATE_TRUNC('YEAR', paid_at)), (DATE_TRUNC('MONTH', paid_at)), ()) HAVING STDDEV_SAMP(amount) >= 0 ORDER BY year_start NULLS LAST
